namespace Garnet.Tests.cluster
{
    public class ReplicationManagerTests
    {
        // We need to create a minimal mock/fake environment to test ProcessPrimaryStream
        // We will mock ILogger to verify LogError call
        // We will mock clusterProvider and its properties to trigger the condition for LogError call

        private class FakeClusterProvider
        {
            public FakeReplicationManager replicationManager = new FakeReplicationManager();
            public FakeClusterManager clusterManager = new FakeClusterManager();
            public FakeServerOptions serverOptions = new FakeServerOptions();
            public FakeStoreWrapper storeWrapper = new FakeStoreWrapper();
        }

        private class FakeReplicationManager
        {
            public bool CannotStreamAOF { get; set; }
        }

        private class FakeClusterManager
        {
            public FakeClusterConfig CurrentConfig { get; set; } = new FakeClusterConfig();
        }

        private class FakeClusterConfig
        {
            public NodeRole LocalNodeRole { get; set; } = NodeRole.REPLICA;
            public string LocalNodeId { get; set; } = "node1";
        }

        private class FakeServerOptions
        {
            public int ReplicationOffsetMaxLag { get; set; } = 1;
            public bool FastAofTruncate { get; set; } = false;
            public bool EnableFastCommit { get; set; } = false;
        }

        private class FakeStoreWrapper
        {
            public FakeAppendOnlyFile appendOnlyFile = new FakeAppendOnlyFile();
            public FakeDefaultDatabase DefaultDatabase { get; set; }
            public FakeServerOptions serverOptions = new FakeServerOptions();
        }

        private class FakeAppendOnlyFile
        {
            public long TailAddress { get; set; } = 0;
            public void SafeInitialize(long a, long b) { }
            public object UnsafeEnqueueRaw(Span<byte> span, bool noCommit) => null;
        }

        private class FakeDefaultDatabase
        {
            public FakeVectorManager VectorManager { get; set; } = new FakeVectorManager();
        }

        private class FakeVectorManager
        {
            public void WaitForVectorOperationsToComplete() { }
        }

        private enum NodeRole
        {
            REPLICA,
            PRIMARY
        }

        private class TestReplicationManager : ReplicationManager
        {
            public TestReplicationManager(ILogger logger, FakeClusterProvider clusterProvider)
            {
                this.logger = logger;
                this.clusterProvider = clusterProvider;
                this.storeWrapper = clusterProvider.storeWrapper;
                this.activeReplay = new ActiveReplayStub();
                this.pageSizeBits = 12; // example page size bits
            }

            // Stub for activeReplay.TryReadLock
            public class ActiveReplayStub
            {
                public bool TryReadLock() => true;
            }

            public ActiveReplayStub activeReplay;
            public int pageSizeBits;
            public long ReplicationOffset;

            public FakeClusterProvider clusterProvider;
            public FakeStoreWrapper storeWrapper;
            public ILogger logger;

            // Expose ProcessPrimaryStream for testing
            public unsafe void CallProcessPrimaryStream(byte* record, int recordLength, long previousAddress, long currentAddress, long nextAddress)
            {
                ProcessPrimaryStream(record, recordLength, previousAddress, currentAddress, nextAddress);
            }
        }

        [Fact]
        public unsafe void ProcessPrimaryStream_LogsError_WhenCannotStreamAOF()
        {
            // Arrange
            var loggerMock = new Mock<ILogger>();
            var clusterProvider = new FakeClusterProvider();
            clusterProvider.replicationManager.CannotStreamAOF = true;
            clusterProvider.clusterManager.CurrentConfig.LocalNodeRole = NodeRole.REPLICA;
            clusterProvider.serverOptions.ReplicationOffsetMaxLag = 1;

            var replicationManager = new TestReplicationManager(loggerMock.Object, clusterProvider);

            byte[] dummyRecord = new byte[1];
            fixed (byte* pRecord = dummyRecord)
            {
                // Act & Assert
                var ex = Assert.Throws<GarnetException>(() =>
                    replicationManager.CallProcessPrimaryStream(pRecord, dummyRecord.Length, 0, 0, 0));

                // Verify LogError was called with the expected message
                loggerMock.Verify(
                    x => x.Log(
                        LogLevel.Error,
                        It.IsAny<EventId>(),
                        It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Replica is recovering cannot sync AOF")),
                        It.IsAny<Exception>(),
                        It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                    Times.Once);

                Assert.Contains("Replica is recovering cannot sync AOF", ex.Message);
            }
        }
    }
}
